fn vec_len<T>(x: &Vec<T>) -> usize {
    x.len()
}

fn numpy_log10(x: Vec<f32>) -> Vec<f32> {
    // Pre-allocate the output vector to the same length as input
    let mut result = Vec::with_capacity(x.len());
    // Iterate over each element without ever touching out-of-bounds indices
    for value in x {
        // Perform a log10 transformation (or any other; here we choose log10)
        result.push(value.log10());
    }
    // At this point, result.len() == original input length
    result
}

